import http.client, ssl
ctx = ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE
for host in ['www.ehiapp.com', 'mycloudclient.com']:
    for path in ['/httpinjector/config', '/httpinjector/login']:
        print(f'===== {host}{path} =====')
        try:
            conn = http.client.HTTPSConnection(host, 443, timeout=15, context=ctx)
            conn.request('GET', path, headers={'User-Agent': 'Evozi-EHI/1.4.1', 'Accept': '*/*'})
            r = conn.getresponse()
            print('status:', r.status, r.reason)
            for k, v in r.getheaders():
                print(f'  {k}: {v}')
            print('body:', r.read(200).decode('utf-8','ignore')[:120])
            conn.close()
        except Exception as e:
            print('ERR:', e)
        print()
